AssistantMessageToolRequest(name='create', tool_call_id='toolu_013JpWD5RoCCzJ59v1ZB9Kcf', arguments={'file_text': ':root {
  --bg: #0a0a0c;
  --bg-1: #111114;
  --bg-2: #16161b;
  --bg-3: #1d1d24;
  --line: #26262e;
  --line-2: #34343e;
  --text: #ececf1;
  --text-2: #a8a8b3;
  --text-3: #6e6e7a;
  --accent: #d4b483;
  --accent-2: #e9d3a8;
  --accent-glow: rgba(212, 180, 131, 0.25);
  --danger: #ff6b6b;
  --success: #6cd99a;
  --radius: 14px;
  --radius-sm: 8px;
  --max: 1240px;
  --shadow-soft: 0 20px 60px -20px rgba(0,0,0,.7);
  --focus: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent-2); }

h1, h2, h3, h4 {
  font-family: "Fraunces", "Cormorant Garamond", "Georgia", serif;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.15;
  margin: 0;
}

p { margin: 0; }

button { font: inherit; color: inherit; cursor: pointer; }

.container { width: 100%; max-width: var(--max); margin: 0 auto; padding: 0 24px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* Skip link */
.skip-link {
  position: absolute; left: 12px; top: -40px;
  background: var(--accent); color: #000; padding: 8px 14px;
  border-radius: var(--radius-sm); font-weight: 600; z-index: 1000;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; outline: none; }

/* Focus */
:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: 4px;
}
button:focus-visible, .btn:focus-visible, .chip:focus-visible,
input:focus-visible, .icon-button:focus-visible {
  box-shadow: var(--focus);
}

/* ====== Header ====== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(10, 10, 12, 0.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 32px;
  height: 72px;
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--text);
  font-family: "Fraunces", serif;
  font-size: 22px; letter-spacing: 0.02em;
}
.brand-mark { width: 28px; height: 28px; color: var(--accent); }
.brand:hover { color: var(--text); }

.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 28px; justify-content: center;
}
.primary-nav a {
  color: var(--text-2);
  font-size: 14px; font-weight: 500;
  letter-spacing: 0.02em;
  padding: 8px 2px;
  border-bottom: 1px solid transparent;
  transition: color .15s, border-color .15s;
}
.primary-nav a:hover { color: var(--text); border-bottom-color: var(--accent); }

.header-actions {
  display: flex; align-items: center; gap: 8px;
}
.search {
  position: relative; display: flex; align-items: center;
}
.search-icon {
  position: absolute; left: 12px; color: var(--text-3);
  pointer-events: none; display: flex;
}
.search input {
  background: var(--bg-2);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 9px 14px 9px 38px;
  border-radius: 999px;
  width: 240px;
  font-size: 14px;
  transition: border-color .15s, background .15s;
}
.search input::placeholder { color: var(--text-3); }
.search input:hover { border-color: var(--line-2); }
.search input:focus { background: var(--bg-3); border-color: var(--accent); outline: none; }

.icon-button {
  position: relative;
  background: transparent; border: 1px solid transparent;
  color: var(--text-2);
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  transition: color .15s, background .15s, border-color .15s;
}
.icon-button:hover { color: var(--text); background: var(--bg-2); border-color: var(--line); }

.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #1a1408;
  font-size: 10px; font-weight: 700;
  min-width: 16px; height: 16px; padding: 0 4px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 2px solid var(--bg);
  box-sizing: content-box;
}

/* ====== Hero ====== */
.hero {
  position: relative;
  overflow: hidden;
  padding: 96px 0 120px;
  border-bottom: 1px solid var(--line);
}
.hero-bg { position: absolute; inset: 0; pointer-events: none; }
.orb {
  position: absolute; border-radius: 50%;
  filter: blur(80px); opacity: .55;
}
.orb-a { width: 520px; height: 520px; left: -120px; top: -160px; background: radial-gradient(circle, #3a2a14, transparent 70%); }
.orb-b { width: 480px; height: 480px; right: -120px; top: 40px; background: radial-gradient(circle, #1a2030, transparent 70%); }
.orb-c { width: 360px; height: 360px; left: 40%; bottom: -180px; background: radial-gradient(circle, #2a1a2a, transparent 70%); }

.hero-inner { position: relative; max-width: 880px; }
.eyebrow {
  font-size: 12px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--text-3);
  margin-bottom: 20px;
}
.eyebrow-accent { color: var(--accent); }

.hero-title {
  font-size: clamp(48px, 8vw, 96px);
  letter-spacing: -0.025em;
  margin-bottom: 24px;
}
.grad {
  background: linear-gradient(110deg, var(--accent) 10%, #fff 60%, var(--accent) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-style: italic;
}
.hero-lede {
  color: var(--text-2);
  font-size: clamp(16px, 1.6vw, 19px);
  max-width: 580px;
  margin-bottom: 36px;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 64px; }

.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  max-width: 640px;
  margin: 0; padding: 24px 0 0;
  border-top: 1px solid var(--line);
}
.hero-stats > div { }
.hero-stats dt {
  font-family: "Fraunces", serif;
  font-size: 18px;
  color: var(--text);
  margin-bottom: 4px;
}
.hero-stats dd {
  margin: 0;
  color: var(--text-3);
  font-size: 13px;
}

/* ====== Buttons ====== */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 14px; font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
  transition: transform .15s, background .15s, border-color .15s, color .15s;
  white-space: nowrap;
}
.btn-primary { background: var(--accent); color: #1a1408; }
.btn-primary:hover { background: var(--accent-2); color: #1a1408; transform: translateY(-1px); }
.btn-ghost {
  background: transparent; color: var(--text);
  border-color: var(--line-2);
}
.btn-ghost:hover { background: var(--bg-2); border-color: var(--text-3); color: var(--text); }

/* ====== Section heads ====== */
section { padding: 96px 0; }
.section-head {
  display: flex; align-items: end; justify-content: space-between;
  gap: 24px; flex-wrap: wrap;
  margin-bottom: 40px;
}
.section-head h2 {
  font-size: clamp(28px, 3.4vw, 40px);
}
.section-link {
  color: var(--text-2);
  font-size: 14px;
  border-bottom: 1px solid var(--line-2);
  padding-bottom: 4px;
}
.section-link:hover { color: var(--accent); border-color: var(--accent); }

/* ====== Categories ====== */
.categories { padding-top: 96px; padding-bottom: 32px; }
.cat-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.cat-card {
  position: relative;
  display: block;
  height: 200px;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .25s ease, border-color .25s;
}
.cat-card:hover { transform: translateY(-4px); border-color: var(--line-2); }
.cat-card span {
  position: absolute; left: 18px; bottom: 16px;
  font-family: "Fraunces", serif;
  font-size: 22px; color: #fff;
  text-shadow: 0 2px 8px rgba(0,0,0,.6);
  z-index: 2;
}
.cat-card::before {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,.7) 100%);
  z-index: 1;
}
.cat-1 { background: linear-gradient(135deg,#2c2218,#0d0a06); }
.cat-2 { background: linear-gradient(135deg,#1c2530,#0a0f15); }
.cat-3 { background: linear-gradient(135deg,#2a1f2a,#0e0810); }
.cat-4 { background: linear-gradient(135deg,#1f2a26,#0a100e); }
.cat-5 { background: linear-gradient(135deg,#2e2520,#100b08); }

/* ====== Featured products ====== */
.filter-chips { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  background: var(--bg-2);
  color: var(--text-2);
  border: 1px solid var(--line);
  padding: 8px 16px;
  font-size: 13px; font-weight: 500;
  border-radius: 999px;
  transition: color .15s, background .15s, border-color .15s;
}
.chip:hover { color: var(--text); border-color: var(--line-2); }
.chip.is-active {
  background: var(--text); color: #0a0a0c;
  border-color: var(--text);
}

.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color .2s, transform .2s;
}
.product:hover { border-color: var(--line-2); transform: translateY(-3px); }

.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: var(--bg-2);
  overflow: hidden;
}
.product-art {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
}
.product-art svg { width: 70%; height: 70%; }
.badge {
  position: absolute; top: 12px; left: 12px;
  background: rgba(10,10,12,.75);
  backdrop-filter: blur(8px);
  color: var(--text);
  font-size: 11px; font-weight: 600;
  letter-spacing: 0.06em; text-transform: uppercase;
  padding: 5px 10px; border-radius: 999px;
  border: 1px solid var(--line-2);
}
.badge.badge-sale { background: var(--accent); color: #1a1408; border-color: transparent; }
.badge.badge-new { background: var(--bg-2); color: var(--accent); border-color: var(--accent); }

.product-wish {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  background: rgba(10,10,12,.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-2);
  display: inline-flex; align-items: center; justify-content: center;
  transition: color .15s, background .15s;
}
.product-wish:hover, .product-wish[aria-pressed="true"] { color: var(--accent); background: rgba(10,10,12,.9); }
.product-wish[aria-pressed="true"] svg { fill: var(--accent); }

.product-body {
  padding: 16px 18px 18px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 11px; color: var(--text-3);
  letter-spacing: 0.1em; text-transform: uppercase;
}
.product-name {
  font-size: 16px; font-weight: 500; color: var(--text);
  font-family: inherit;
}
.product-name a { color: inherit; }
.product-name a:hover { color: var(--accent-2); }
.product-name a::after {
  content: ""; position: absolute; inset: 0; z-index: 1;
}
.product-media { z-index: 2; } /* keep wish/badge clickable */
.product-wish { z-index: 3; }

.product-foot {
  margin-top: auto;
  padding-top: 10px;
  display: flex; align-items: center; justify-content: space-between;
}
.price { font-size: 15px; color: var(--text); font-weight: 600; }
.price-old { color: var(--text-3); text-decoration: line-through; margin-left: 6px; font-weight: 400; font-size: 13px; }
.rating {
  display: inline-flex; align-items: center; gap: 4px;
  color: var(--text-3); font-size: 12px;
}
.rating svg { color: var(--accent); }

/* relative wrapper so name link spans card */
.product { position: relative; }

/* ====== Deals ====== */
.deals { background: linear-gradient(180deg, var(--bg) 0%, var(--bg-1) 100%); }
.countdown {
  font-size: 14px; color: var(--text-2);
}
.countdown time {
  font-family: "JetBrains Mono", ui-monospace, "SF Mono", monospace;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  font-size: 16px;
  margin-left: 6px;
}
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 16px;
}
.deal {
  position: relative;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  display: flex; flex-direction: column; gap: 10px;
  transition: border-color .2s, transform .2s;
  min-height: 180px;
}
.deal:hover { border-color: var(--line-2); }
.deal h3 { font-size: 22px; }
.deal p { color: var(--text-2); font-size: 14px; }
.deal-feature {
  grid-row: span 2;
  background:
    radial-gradient(circle at 80% 20%, rgba(212,180,131,.18), transparent 55%),
    linear-gradient(160deg, #1c1812 0%, #0d0c10 100%);
  border-color: rgba(212,180,131,.25);
  padding: 36px;
  justify-content: flex-end;
}
.deal-feature h3 { font-size: clamp(28px, 3.2vw, 40px); margin-bottom: 4px; }
.deal-feature p { font-size: 16px; max-width: 360px; margin-bottom: 12px; }

.deal-tag {
  align-self: flex-start;
  display: inline-block;
  background: var(--accent); color: #1a1408;
  font-size: 12px; font-weight: 700;
  letter-spacing: 0.04em;
  padding: 5px 10px;
  border-radius: 6px;
}
.deal-tag-2 { background: #d97a5b; color: #1a0e09; }
.deal-tag-3 { background: #6b8eb4; color: #07111c; }
.deal-tag-4 { background: var(--bg-3); color: var(--accent); border: 1px solid var(--accent); }

.deal-link {
  margin-top: auto;
  align-self: flex-start;
  color: var(--accent);
  font-size: 14px; font-weight: 600;
  border-bottom: 1px solid transparent;
  transition: border-color .15s;
}
.deal-link:hover { border-color: var(--accent); }

/* ====== Editorial ====== */
.editorial { background: var(--bg); }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.story {
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color .2s, transform .2s;
}
.story:hover { border-color: var(--line-2); transform: translateY(-3px); }
.story-image {
  aspect-ratio: 16 / 11;
  position: relative;
  overflow: hidden;
}
.story-image::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,.55) 100%);
}
.story-image-1 {
  background:
    radial-gradient(circle at 30% 30%, rgba(212,180,131,.4), transparent 50%),
    linear-gradient(135deg,#2a2014 0%, #0d0a06 100%);
}
.story-image-2 {
  background:
    repeating-linear-gradient(45deg, rgba(255,255,255,.04) 0 2px, transparent 2px 6px),
    linear-gradient(135deg,#22272d 0%, #0a0d10 100%);
}
.story-image-3 {
  background:
    radial-gradient(circle at 50% 70%, rgba(233,211,168,.25), transparent 30%),
    linear-gradient(180deg,#10131a 0%, #050608 100%);
}
.story-lead .story-image { aspect-ratio: 16 / 13; }
.story-lead h3 { font-size: 28px; }

.story-body {
  padding: 22px 24px 26px;
  display: flex; flex-direction: column; gap: 10px;
}
.story-meta {
  display: flex; align-items: center; gap: 12px;
  color: var(--text-3); font-size: 12px;
  letter-spacing: 0.04em;
}
.tag {
  background: var(--bg-3); color: var(--accent);
  padding: 3px 8px; border-radius: 4px;
  font-size: 11px; font-weight: 600;
  letter-spacing: 0.08em; text-transform: uppercase;
}
.story h3 { font-size: 22px; }
.story h3 a { color: var(--text); }
.story h3 a:hover { color: var(--accent-2); }
.story-body p:last-child { color: var(--text-2); font-size: 14px; }

/* ====== Newsletter ====== */
.newsletter {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--bg-1);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter h2 { font-size: clamp(26px, 3vw, 36px); margin-bottom: 8px; }
.newsletter p { color: var(--text-2); }

.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: center;
}
.news-form input {
  background: var(--bg-2);
  border: 1px solid var(--line);
  color: var(--text);
  padding: 14px 18px;
  border-radius: 999px;
  font-size: 15px;
}
.news-form input::placeholder { color: var(--text-3); }
.news-form input:focus { outline: none; border-color: var(--accent); background: var(--bg-3); }
.news-form input[aria-invalid="true"] { border-color: var(--danger); }
.news-form .btn { padding: 14px 24px; }
.news-status {
  grid-column: 1 / -1;
  font-size: 13px;
  min-height: 18px;
  color: var(--text-2);
  padding-left: 18px;
}
.news-status.is-error { color: var(--danger); }
.news-status.is-success { color: var(--success); }

/* ====== Footer ====== */
.site-footer {
  background: var(--bg);
  border-top: 1px solid var(--line);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--line);
}
.footer-tag { color: var(--text-3); margin-top: 12px; max-width: 280px; }
.site-footer nav h2 {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text);
  margin-bottom: 16px;
}
.site-footer nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-direction: column; gap: 10px;
}
.site-footer nav a { color: var(--text-2); font-size: 14px; }
.site-footer nav a:hover { color: var(--accent); }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 28px;
  color: var(--text-3); font-size: 13px;
  flex-wrap: wrap; gap: 12px;
}
.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 20px; }
.legal a { color: var(--text-3); }
.legal a:hover { color: var(--accent); }

/* ====== Toast ====== */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--line-2);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 14px;
  box-shadow: var(--shadow-soft);
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s, transform .25s;
  z-index: 100;
  max-width: calc(100vw - 32px);
}
.toast.is-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ====== Responsive ====== */
@media (max-width: 1024px) {
  .header-inner { grid-template-columns: auto auto; gap: 16px; }
  .primary-nav { display: none; }
  .search input { width: 180px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-row: span 1; grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-column: span 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  section { padding: 64px 0; }
  .hero { padding: 64px 0 80px; }
  .search { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: span 1; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: span 1; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
  .news-form { grid-template-columns: 1fr; }
  .news-form .btn { width: 100%; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .hero-stats { grid-template-columns: 1fr; gap: 12px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 420px) {
  .product-grid { grid-template-columns: 1fr; }
  .cat-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .chip, .icon-button, .search input, .news-form input {
    border: 1px solid CanvasText;
  }
  .btn-primary, .deal-tag, .cart-count { background: Highlight; color: HighlightText; }
  :focus-visible { outline: 2px solid Highlight; box-shadow: none; }
  .grad { color: CanvasText; -webkit-text-fill-color: CanvasText; background: none; }
}
