    let diff = Math.max(0, end - now);
    const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
    diff %= 3600000;
    const m = String(Math.floor(diff / 60000)).padStart(2, '0');
    diff %= 60000;
    const s = String(Math.floor(diff / 1000)).padStart(2, '0');
    cd.textContent = `${h}:${m}:${s}`;
  }
  tickCountdown();
  setInterval(tickCountdown, 1000);

  // ---- Newsletter ----
  const newsForm = document.getElementById('newsForm');
  const newsInput = document.getElementById('news-email');
  const newsStatus = document.getElementById('news-status');
  newsForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const value = newsInput.value.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    newsStatus.classList.remove('is-error', 'is-success');
    if (!valid) {
      newsInput.setAttribute('aria-invalid', 'true');
      newsStatus.textContent = 'Please enter a valid email address.';
      newsStatus.classList.add('is-error');
      newsInput.focus();
      return;
    }
    newsInput.removeAttribute('aria-invalid');
    newsStatus.textContent = 'Thanks — check your inbox to confirm your subscription.';
    newsStatus.classList.add('is-success');
    newsForm.reset();
  });

  // ---- Init ----
  renderProducts('all');
})();
