  };

  // ---- Render products ----
  const grid = document.getElementById('productGrid');
  function renderProducts(filter) {
    const list = filter && filter !== 'all'
      ? products.filter(p => p.tag === filter)
      : products;
    grid.innerHTML = list.map(p => {
      const badge = p.badge
        ? `<span class="badge ${p.badge === 'Sale' ? 'badge-sale' : 'badge-new'}">${p.badge}</span>`
        : '';
      const oldP = p.oldPrice ? `<span class="price-old">$${p.oldPrice}</span>` : '';
      return `
        <li class="product" data-tag="${p.tag}">
          <div class="product-media">
            ${badge}
            <button type="button" class="product-wish" aria-pressed="false" aria-label="Save ${p.name} to wishlist">
              <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
                <path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
              </svg>
            </button>
            <div class="product-art" aria-hidden="true">${arts[p.art] || ''}</div>
          </div>
          <div class="product-body">
            <span class="product-cat">${p.cat}</span>
            <h3 class="product-name"><a href="#">${p.name}</a></h3>
            <div class="product-foot">
              <div class="price">$${p.price}${oldP}</div>
              <span class="rating" role="img" aria-label="Rated ${p.rating} out of 5">
                <svg viewBox="0 0 24 24" width="13" height="13" aria-hidden="true" focusable="false"><path d="M12 2l2.9 6.9 7.1.6-5.4 4.7 1.7 7-6.3-3.9-6.3 3.9 1.7-7L2 9.5l7.1-.6z" fill="currentColor"/></svg>
                ${p.rating.toFixed(1)}
              </span>
            </div>
          </div>
        </li>`;
    }).join('');
    bindWishButtons();
  }

  // ---- Wishlist toggle ----
  function bindWishButtons() {
    grid.querySelectorAll('.product-wish').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const pressed = btn.getAttribute('aria-pressed') === 'true';
        btn.setAttribute('aria-pressed', String(!pressed));
        btn.setAttribute(
          'aria-label',
          (pressed ? 'Save ' : 'Remove ') + btn.getAttribute('aria-label').replace(/^(Save |Remove )/, '').replace(/ to wishlist$| from wishlist$/, '') + (pressed ? ' to wishlist' : ' from wishlist')
        );
        toast(pressed ? 'Removed from wishlist' : 'Added to wishlist');
      });
    });
  }

  // ---- Filter chips ----
  const chips = document.querySelectorAll('.chip');
  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      chips.forEach(c => {
        c.classList.remove('is-active');
        c.setAttribute('aria-selected', 'false');
      });
      chip.classList.add('is-active');
      chip.setAttribute('aria-selected', 'true');
      renderProducts(chip.dataset.filter);
    });
  });

  // ---- Cart ----
  let cartCount = 0;
  const cartCountEl = document.getElementById('cartCount');
  const cartBtn = document.getElementById('cartButton');
  cartBtn.addEventListener('click', () => {
    cartCount += 1;
    cartCountEl.textContent = String(cartCount);
    cartBtn.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}`);
    toast(`Cart updated · ${cartCount} item${cartCount === 1 ? '' : 's'}`);
  });

  // ---- Toast ----
  const toastEl = document.getElementById('toast');
  let toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove('is-visible'), 2200);
  }

  // ---- Countdown ----
  const cd = document.getElementById('countdown');
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  function tickCountdown() {
    const now = new Date();
    let diff = Math.max(0, end - now);
    const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
    diff %= 3600000;
    const m = String(Math.floor(diff / 60000)).padStart(2, '0');
    diff %= 60000;
    const s = String(Math.floor(diff / 1000)).padStart(2, '0');
    cd.textContent = `${h}:${m}:${s}`;
  }
  tickCountdown();
  setInterval(tickCountdown, 1000);

  // ---- Newsletter ----
  const newsForm = document.getElementById('newsForm');
  const newsInput = document.getElementById('news-email');
  const newsStatus = document.getElementById('news-status');
  newsForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const value = newsInput.value.trim();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    newsStatus.classList.remove('is-error', 'is-success');
    if (!valid) {
      newsInput.setAttribute('aria-invalid', 'true');
      newsStatus.textContent = 'Please enter a valid email address.';
      newsStatus.classList.add('is-error');
      newsInput.focus();
      return;
    }
    newsInput.removeAttribute('aria-invalid');
    newsStatus.textContent = 'Thanks — check your inbox to confirm your subscription.';
    newsStatus.classList.add('is-success');
    newsForm.reset();
  });

  // ---- Init ----
  renderProducts('all');
})();
